bool isPalindrome(const string& s) {
    int l = 0, r = (int)s.size() - 1;
    while (l < r) {
        while (l < r && !isalnum((unsigned char)s[l])) ++l;   // skip junk from the left
        while (l < r && !isalnum((unsigned char)s[r])) --r;   // and from the right
        if (tolower((unsigned char)s[l]) != tolower((unsigned char)s[r])) return false;
        ++l; --r;
    }
    return true;
}

bool isAnagram(const string& s, const string& t) {
    if (s.size() != t.size()) return false;    // cheap reject
    int count[26] = {0};
    for (size_t i = 0; i < s.size(); ++i) {
        ++count[s[i] - 'a'];
        --count[t[i] - 'a'];
    }
    for (int c : count) if (c) return false;
    return true;
}

