def is_anagram(s: str, t: str) -> bool:
    if len(s) != len(t):          # cheap reject
        return False
    count = [0] * 26
    for cs, ct in zip(s, t):
        count[ord(cs) - 97] += 1
        count[ord(ct) - 97] -= 1
    return not any(count)

