string truncateSentence(const string& s, int k) {
    int words = 0;
    for (size_t i = 0; i < s.size(); ++i) {
        if (s[i] == ' ') {
            ++words;
            if (words == k) return s.substr(0, i);   // cut AT this space
        }
    }
    return s;                                        // fewer than k+1 words
}

