string interpret(const string& command) {
    string out;
    for (size_t i = 0; i < command.size(); ++i) {
        if (command[i] == 'G') out += 'G';
        else if (command[i + 1] == ')') { out += 'o'; i += 1; }   // "()"
        else                            { out += "al"; i += 3; }  // "(al)"
    }
    return out;
}

