def interpret(command: str) -> str:
    out = []
    i = 0
    while i < len(command):
        if command[i] == 'G':
            out.append('G'); i += 1
        elif command[i + 1] == ')':
            out.append('o'); i += 2          # "()"
        else:
            out.append('al'); i += 4         # "(al)"
    return "".join(out)

