string capitalizeWords(string s) {
    bool newWord = true;
    for (char& c : s) {
        if (c == ' ') { newWord = true; continue; }
        c = newWord ? toupper((unsigned char)c) : tolower((unsigned char)c);
        newWord = false;
    }
    return s;
}

