def capitalize_words(s: str) -> str:
    out = []
    new_word = True
    for c in s:
        if c == ' ':
            new_word = True
            out.append(c)
            continue
        out.append(c.upper() if new_word else c.lower())
        new_word = False
    return "".join(out)

